{"content":"1|{% extends "layouts/base.html" %}
2|
3|{% block content %}
4|<div class="d-flex align-items-center justify-content-between border-bottom pb-3 mb-4"><div><h3 class="mb-1">版本审批</h3><div class="small text-muted">比较提交版本并记录批准、驳回或修改意见</div></div></div>
5|<div id="approval-list" class="alert alert-light border" role="status">暂无待审批版本。</div>
6|{% endblock %}
7|{% block scripts %}<script src="/static/js/review/approval_renderer.js"></script><script src="/static/js/review/approvals.js"></script>{% endblock %}","total_lines":7,"file_size":554,"truncated":false,"is_binary":false,"is_image":false}

{"content":"1|(() => {
2|    const container = document.getElementById('approval-list');
3|    if (!container) return;
4|
5|    const button = (label, icon, className, onClick) => {
6|        const element = document.createElement('button');
7|        element.type = 'button';
8|        element.className = `btn btn-sm ${className}`;
9|        element.innerHTML = `<i class="bi ${icon} me-1" aria-hidden="true"></i>${label}`;
10|        element.addEventListener('click', onClick);
11|        return element;
12|    };
13|
14|    const writeReview = async (submission, action, reviewComment = '') => {
15|        if (action === 'return' && !reviewComment.trim()) {
16|            throw new Error('退回时必须填写修改意见');
17|        }
18|        const options = {method: 'POST'};
19|        if (action === 'return') {
20|            options.headers = {'Content-Type': 'application/json'};
21|            options.body = JSON.stringify({review_comment: reviewComment.trim()});
22|        }
23|        const response = await aiworkerApi.request(
24|            `/api/workflow/submissions/${submission.id}/${action}`,
25|            options,
26|        );
27|        const data = await response.json();
28|        if (!response.ok) throw new Error(data.detail || '审批操作失败');
29|        await loadApprovals();
30|    };
31|
32|    const renderSubmission = (task, submission) => {
33|        const section = document.createElement('section');
34|        section.className = 'border-bottom py-3';
35|        const heading = document.createElement('div');
36|        heading.className = 'd-flex justify-content-between gap-3 mb-2';
37|        const identity = document.createElement('div');
38|        const resourceType = document.createElement('strong');
39|        resourceType.textContent = window.aiworkerApprovalRenderer.resourceTypeLabel(submission.resource_type);
40|        const resourceVersion = document.createElement('div');
41|        resourceVersion.className = 'small text-muted';
42|        resourceVersion.textContent = `${submission.resource_id} · v${submission.version}`;
43|        identity.append(resourceType, resourceVersion);
44|        const status = document.createElement('span');
45|        status.className = 'badge text-bg-warning';
46|        status.textContent = '待审批';
47|        heading.append(identity, status);
48|        const content = window.aiworkerApprovalRenderer.render(
49|            submission.resource_type,
50|            submission.content_snapshot,
51|        );
52|        const comment = document.createElement('textarea');
53|        comment.className = 'form-control form-control-sm mb-2';
54|        comment.rows = 2;
55|        comment.placeholder = '退回修改意见（退回时必填）';
56|        comment.setAttribute('aria-label', '退回修改意见');
57|        const error = document.createElement('div');
58|        error.className = 'small text-danger mb-2';
59|        const actions = document.createElement('div');
60|        actions.className = 'd-flex justify-content-end gap-2';
61|        if (task.can_approve) {
62|            actions.appendChild(button('批准', 'bi-check-lg', 'btn-success', async () => {
63|                error.textContent = '';
64|                try { await writeReview(submission, 'approve'); } catch (exc) { error.textContent = exc.message; }
65|            }));
66|        }
67|        if (task.can_return) {
68|            actions.appendChild(button('退回', 'bi-arrow-return-left', 'btn-outline-danger', async () => {
69|                error.textContent = '';
70|                try { await writeReview(submission, 'return', comment.value); } catch (exc) { error.textContent = exc.message; }
71|            }));
72|        }
73|        const contentLabel = document.createElement('div');
74|        contentLabel.className = 'small fw-semibold text-muted mt-4 mb-2';
75|        contentLabel.textContent = '提交内容';
76|        section.append(heading, comment, error, actions, contentLabel, content);
77|        return section;
78|    };
79|
80|    async function loadApprovals() {
81|        container.className = 'alert alert-light border';
82|        container.textContent = '正在加载待审批版本...';
83|        try {
84|            const taskResponse = await aiworkerApi.request('/api/workflow/tasks');
85|            const tasks = await taskResponse.json();
86|            if (!taskResponse.ok) throw new Error(tasks.detail || '任务加载失败');
87|            const approvalStages = new Set(['brief', 'characters', 'outline', 'beats', 'delivery']);
88|            const requestedTaskId = new URLSearchParams(window.location.search).get('task_id');
89|            const waiting = (tasks || []).filter(task =>
90|                approvalStages.has(task.task_type)
91|                && (!requestedTaskId || task.id === requestedTaskId)
92|                && task.status === 'waiting_review' && (task.can_approve || task.can_return)
93|            );
94|            const rows = [];
95|            for (const task of waiting) {
96|                const response = await aiworkerApi.request(`/api/workflow/tasks/${task.id}/submissions`);
97|                if (!response.ok) continue;
98|                const submissions = await response.json();
99|                const submission = submissions.filter(item => item.status === 'submitted').at(-1);
100|                if (submission) rows.push([task, submission]);
101|            }
102|            container.replaceChildren();
103|            if (!rows.length) {
104|                container.className = 'alert alert-light border';
105|                container.textContent = '暂无待审批版本。';
106|                return;
107|            }
108|            container.className = '';
109|            rows.forEach(([task, submission]) => container.appendChild(renderSubmission(task, submission)));
110|        } catch (error) {
111|            container.className = 'alert alert-danger';
112|            container.textContent = error.message || '审批列表加载失败';
113|        }
114|    }
115|
116|    loadApprovals();
117|    document.querySelector('[data-workspace-page="review-approvals"]')?.setAttribute('data-ready', 'true');
118|})();","total_lines":118,"file_size":5880,"truncated":false,"is_binary":false,"is_image":false}

