def test_approval_flow_api_includes_pending_reviewed_and_own_submissions(
    identity_repository: IdentityRepository,
    repository: WorkflowRepository,
):
    author = _principal(identity_repository, "flow_author", "creative_planner")
    owner = _principal(identity_repository, "flow_owner", "project_owner")
    other = _principal(identity_repository, "flow_other", "creative_planner")
    admin = _principal(identity_repository, "flow_admin", "system_admin")
    service = TransitionService(repository)

    repository.add_project_member("flow-project", owner.user_id, "project_owner", admin)
    repository.add_project_member("flow-project", author.user_id, "creative_planner", admin)
    repository.add_project_member("flow-project", other.user_id, "creative_planner", admin)

    def submitted_task(workflow_id: str, actor: Principal) -> dict:
        task = repository.create_task(
            workflow_id,
            "custom_review",
            "creative_planner",
            project_id="flow-project",
            actor=admin,
        )
        repository.assign_task(task["id"], actor.user_id, admin)
        repository.start_task(task["id"], actor)
        draft = service.create_submission(
            task["id"], "custom", workflow_id, {"title": workflow_id}, actor
        )
        return service.submit(draft["id"], actor)

    approved = submitted_task("flow-approved", author)
    service.approve(approved["id"], owner)
    returned = submitted_task("flow-returned", author)
    service.return_submission(returned["id"], owner, "请修改冲突")
    pending = submitted_task("flow-pending", other)

    owner_rows = _client(identity_repository, repository, owner).get(
        "/api/workflow/approval-flow"
    )
    author_rows = _client(identity_repository, repository, author).get(
        "/api/workflow/approval-flow"
    )

    assert owner_rows.status_code == 200
    assert {row["status"] for row in owner_rows.json()} >= {
        "submitted", "approved", "returned"
    }
    assert any(
        row["id"] == approved["id"] and row["relation"] == "reviewed_by_me"
        for row in owner_rows.json()
    )
    assert any(
        row["id"] == pending["id"] and row["relation"] == "pending_for_me"
        for row in owner_rows.json()
    )
    assert author_rows.status_code == 200
    assert {row["id"] for row in author_rows.json()} >= {approved["id"], returned["id"]}
    assert all(row["relation"] == "submitted_by_me" for row in author_rows.json())
    assert all("submitted_by_display_name" in row for row in owner_rows.json())
    assert all("reviewed_by_display_name" in row for row in owner_rows.json())


