    def list_approval_flow(
        self, actor: Principal | dict[str, Any]
    ) -> list[dict[str, Any]]:
        actor_id = self._actor_id(actor)
        with self.identity_repository.connect() as connection:
            live_actor = self._live_actor(connection, actor_id)
            rows = connection.execute(
                """
                SELECT s.*, t.workflow_id, t.task_type, t.project_id, t.topic_id,
                       submitter.display_name AS submitted_by_display_name,
                       reviewer.display_name AS reviewed_by_display_name
                FROM workflow_submissions s
                JOIN workflow_tasks t ON t.id = s.task_id
                LEFT JOIN users submitter ON submitter.id = s.submitted_by
                LEFT JOIN users reviewer ON reviewer.id = s.reviewed_by
                WHERE s.status IN ('submitted', 'approved', 'returned', 'superseded')
                ORDER BY COALESCE(s.reviewed_at, s.submitted_at, s.updated_at) DESC, s.id DESC
                """
            ).fetchall()
            result = []
            for row in rows:
                submission = self._submission_dict(row)
                if submission["submitted_by"] == actor_id:
                    submission["relation"] = "submitted_by_me"
                elif submission["reviewed_by"] == actor_id:
                    submission["relation"] = "reviewed_by_me"
                elif submission["status"] == "submitted" and self._can_review_task_in_connection(
                    connection, submission["task_id"], live_actor
                ):
                    submission["relation"] = "pending_for_me"
                elif live_actor["is_system_admin"]:
                    submission["relation"] = "visible_to_admin"
                else:
                    continue
                result.append(submission)
        return result

    def _can_review_task_in_connection(
        self,
        connection: sqlite3.Connection,
        task_id: str,
        live_actor: dict[str, Any],
    ) -> bool:
        if live_actor["is_system_admin"]:
            return True
        if not ({"version.approve", "version.return"} & set(live_actor["permissions"])):
            return False
        task = self._require_task(connection, task_id)
        project_id = task.get("project_id")
        if project_id is None:
            return bool(task.get("topic_id") is not None and "project.manage" in live_actor["permissions"])
        if "project_owner" not in live_actor["role_codes"]:
            return False
        try:
            self._assert_managed_project_membership(connection, project_id, live_actor)
            return True
        except PermissionError:
            return not self._project_has_active_manager(connection, project_id)

