{"content":"(() => {
    const container = document.getElementById('review-task-list');
    const refresh = document.getElementById('refresh-review-tasks');
    const relationFilter = document.getElementById('approval-flow-relation');
    const statusFilter = document.getElementById('approval-flow-status');
    if (!container) return;

    let rows = [];
    const statusMeta = {
        submitted: ['待审批', 'text-bg-warning'],
        approved: ['已通过', 'text-bg-success'],
        returned: ['已打回', 'text-bg-danger'],
        superseded: ['已替代', 'text-bg-secondary'],
    };
    const relationMeta = {
        pending_for_me: '提交给我的',
        submitted_by_me: '我提交的',
        reviewed_by_me: '我审批的',
        visible_to_admin: '全部审批流',
    };
    const typeLabels = {
        topic_decision: '选题决策', source_package: '素材包', breakdown: '剧目拆解',
        brief: '创作任务书', characters: '人物关系', outline: '分集大纲',
        beats: '单集 Beats', delivery: '成果交付', custom: '版本审批',
    };

    const formatTime = value => value
        ? new Date(Number(value) * 1000).toLocaleString('zh-CN', {hour12: false})
        : '—';

    const render = () => {
        const relation = relationFilter?.value || 'all';
        const status = statusFilter?.value || 'all';
        const visible = rows.filter(row =>
            (relation === 'all' || row.relation === relation)
            && (status === 'all' || row.status === status)
        );
        container.replaceChildren();
        if (!visible.length) {
            container.className = 'alert alert-light border';
            container.textContent = rows.length ? '当前筛选条件下暂无审批记录。' : '暂无审批流记录。';
            return;
        }
        container.className = 'vstack gap-3';
        visible.forEach(row => {
            const card = document.createElement('article');
            card.className = 'card bg-body-tertiary border-secondary-subtle';
            const body = document.createElement('div');
            body.className = 'card-body';
            const [statusLabel, statusClass] = statusMeta[row.status] || [row.status, 'text-bg-secondary'];
            const canReview = row.relation === 'pending_for_me' && row.status === 'submitted';
            body.innerHTML = `
                <div class="d-flex flex-wrap justify-content-between align-items-start gap-3">
                  <div>
                    <div class="d-flex flex-wrap align-items-center gap-2 mb-1">
                      <strong>${typeLabels[row.resource_type] || row.resource_type}</strong>
                      <span class="badge ${statusClass}">${statusLabel}</span>
                      <span class="badge text-bg-info">${relationMeta[row.relation] || row.relation}</span>
                    </div>
                    <div class="small text-muted">${row.resource_id} · v${row.version} · ${row.project_id ? `项目 ${row.project_id}` : `选题 ${row.topic_id || '—'}`}</div>
                  </div>
                  <a class="btn btn-sm ${canReview ? 'btn-primary' : 'btn-outline-info'}" href="/review/approvals?task_id=${encodeURIComponent(row.task_id)}">
                    <i class="bi bi-eye me-1"></i>${canReview ? '立即审批' : '查看审批详情'}
                  </a>
                </div>
                <div class="row g-3 mt-1 small">
                  <div class="col-md-3"><span class="text-muted">提交人</span><div>${row.submitted_by_display_name || '—'}</div></div>
                  <div class="col-md-3"><span class="text-muted">提交时间</span><div>${formatTime(row.submitted_at)}</div></div>
                  <div class="col-md-3"><span class="text-muted">审批人</span><div>${row.reviewed_by_display_name || '待审批'}</div></div>
                  <div class="col-md-3"><span class="text-muted">审批时间</span><div>${formatTime(row.reviewed_at)}</div></div>
                </div>
                ${row.review_comment ? `<div class="alert alert-secondary py-2 mt-3 mb-0"><span class="fw-semibold">审批意见：</span>${row.review_comment}</div>` : ''}
            `;
            card.appendChild(body);
            container.appendChild(card);
        });
    };

    const load = async () => {
        container.className = 'alert alert-light border';
        container.textContent = '正在加载审批流...';
        try {
            const response = await aiworkerApi.request('/api/workflow/approval-flow');
            const data = await response.json();
            if (!response.ok) throw new Error(data.detail || '审批流加载失败');
            rows = Array.isArray(data) ? data : [];
            render();
        } catch (error) {
            container.className = 'alert alert-danger';
            container.textContent = error.message || '审批流加载失败';
        }
    };

    refresh?.addEventListener('click', load);
    relationFilter?.addEventListener('change', render);
    statusFilter?.addEventListener('change', render);
    load();
})();
